CapabilityEntry? findCapability(String id) {
  for (final c in kCapabilities) { if (c.id == id) return c; }
  return null;
}
List<CapabilityEntry> byPhase(String phase) => kCapabilities.where((c) => c.phase == phase).toList();
List<CapabilityEntry> byPhaseEnum(LoutePhase phase) => byPhase(phase.name);

class CatalogMeta {
  static const String version = '1.5.5';
  static int get totalCapabilities => kCapabilities.length;
  static int get totalPhases => LoutePhase.values.length;
  static Map<String, int> get phaseCounts {
    final counts = <String, int>{};
    for (final c in kCapabilities) { counts[c.phase] = (counts[c.phase] ?? 0) + 1; }
    return counts;
  }
}
